using Microsoft.AspNetCore.Mvc; using KKBOT.Application.Queries; using KKBOT.Contracts.Instances; namespace KKBOT.Dashboard.Controllers; [ApiController] [Route("api/[controller]")] public class InstancesController : ControllerBase { private readonly IMediator _mediator; public InstancesController(IMediator mediator) => _mediator = mediator; [HttpGet] public async Task<IReadOnlyList<InstanceDto>> Get(CancellationToken ct) => await _mediator.Send(new GetInstancesQuery(), ct); }